import{_ as a,o as s,c as n,a3 as e}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"日志页：自查问题","description":"","frontmatter":{},"headers":[],"relativePath":"use/log-page.md","filePath":"use/log-page.md","lastUpdated":1791133906000}'),r={name:"use/log-page.md"};function l(i,t,o,d,h,p){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="日志页-自查问题" tabindex="-1">日志页：自查问题 <a class="header-anchor" href="#日志页-自查问题" aria-label="Permalink to &quot;日志页：自查问题&quot;">​</a></h1><p><strong>排查问题的第一现场。</strong> 出任何异常，先来这里看。</p><h2 id="页面上有什么" tabindex="-1">页面上有什么 <a class="header-anchor" href="#页面上有什么" aria-label="Permalink to &quot;页面上有什么&quot;">​</a></h2><ol><li><strong>级别筛选按钮</strong> —— 全部 / 信息 / 告警 / 错误</li><li><strong>日志列表</strong> —— 每条带时间和级别</li><li><strong>复制全部日志</strong> 按钮</li><li><strong>日志文件路径</strong> 显示</li></ol><h2 id="三级日志" tabindex="-1">三级日志 <a class="header-anchor" href="#三级日志" aria-label="Permalink to &quot;三级日志&quot;">​</a></h2><p>框架把日志分成三个级别：</p><table tabindex="0"><thead><tr><th>级别</th><th>含义</th><th>显示颜色</th></tr></thead><tbody><tr><td><strong>信息</strong></td><td>正常运作记录（加载了哪些 Mod、改了哪些参数）</td><td>正常</td></tr><tr><td><strong>告警</strong></td><td>需要注意但不影响运行（Mod 冲突、找不到舰级）</td><td>橙色</td></tr><tr><td><strong>错误</strong></td><td>真的出错了（引擎异常、加载失败）</td><td>红色</td></tr></tbody></table><h2 id="筛选" tabindex="-1">筛选 <a class="header-anchor" href="#筛选" aria-label="Permalink to &quot;筛选&quot;">​</a></h2><p>顶部四个按钮：</p><table tabindex="0"><thead><tr><th>按钮</th><th>显示</th></tr></thead><tbody><tr><td><strong>全部</strong></td><td>所有日志</td></tr><tr><td><strong>信息</strong></td><td>只看正常运行记录</td></tr><tr><td><strong>告警</strong></td><td>只看告警（<strong>排查冲突时用这个</strong>）</td></tr><tr><td><strong>错误</strong></td><td>只看错误（<strong>排查崩溃时用这个</strong>）</td></tr></tbody></table><p>当前档位会用 <code>●</code> 标出。</p><div class="tip custom-block"><p class="custom-block-title">两个最常用的操作</p><ol><li><strong>想看有没有冲突</strong> → 点「告警」</li><li><strong>想看有没有真出错</strong> → 点「错误」</li></ol></div><h2 id="复制全部日志" tabindex="-1">复制全部日志 <a class="header-anchor" href="#复制全部日志" aria-label="Permalink to &quot;复制全部日志&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">这个按钮非常重要</p><p>点「<strong>复制全部日志</strong>」→ 把<strong>完整日志</strong>（不受筛选影响）复制到剪贴板 → 发给作者，作者就能看到全部线索。</p></div><p>注意：即使你当前筛选的是「错误」，<strong>复制出来的仍然是全部日志</strong>。这是故意的 —— 排查问题需要完整上下文。</p><h2 id="日志存在哪" tabindex="-1">日志存在哪 <a class="header-anchor" href="#日志存在哪" aria-label="Permalink to &quot;日志存在哪&quot;">​</a></h2><p>页面会显示日志文件的路径：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Android/data/&lt;游戏包名&gt;/files/AFMOD_log.txt</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="为什么日志要写文件" tabindex="-1">为什么日志要写文件 <a class="header-anchor" href="#为什么日志要写文件" aria-label="Permalink to &quot;为什么日志要写文件&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">这是框架的一条重要设计原则</p><p><strong>只存内存的日志等于没有日志。</strong></p><p>如果日志只放在内存里，游戏一关就全丢了。真机上遇到问题想找人帮忙看，<strong>拿不出任何证据</strong>。</p><p>所以框架的日志策略是：</p><table tabindex="0"><thead><tr><th>策略</th><th>原因</th></tr></thead><tbody><tr><td><strong>落盘写文件</strong></td><td>游戏关了还在</td></tr><tr><td><strong>累积一定条数才写一次</strong></td><td>避免频繁 IO 卡顿（IO 在主线程）</td></tr><tr><td><strong>退出时补刷</strong></td><td>保证最后几条不丢</td></tr><tr><td><strong>超过 200 KB 截断</strong></td><td>防止文件无限增长，且保留<strong>最近的</strong>部分</td></tr><tr><td><strong>每次启动写分隔行</strong></td><td>区分不同次运行</td></tr></tbody></table></div><h2 id="日志里能看到什么" tabindex="-1">日志里能看到什么 <a class="header-anchor" href="#日志里能看到什么" aria-label="Permalink to &quot;日志里能看到什么&quot;">​</a></h2><h3 id="启动时" tabindex="-1">启动时 <a class="header-anchor" href="#启动时" aria-label="Permalink to &quot;启动时&quot;">​</a></h3><ul><li>扫到了哪些 Mod</li><li>每个 Mod 的名字、作者、版本</li><li>参数被改成了什么</li><li>有没有冲突</li></ul><h3 id="运行时" tabindex="-1">运行时 <a class="header-anchor" href="#运行时" aria-label="Permalink to &quot;运行时&quot;">​</a></h3><ul><li>引擎的报错（Unity 的 Error / Exception / Assert 会被桥接进日志）</li><li>舰船/模型的加载结果</li><li>分享码的导入结果</li></ul><p><code>debug.verbose</code> 打开后会写更详细的日志。</p><h2 id="一个典型的自查流程" tabindex="-1">一个典型的自查流程 <a class="header-anchor" href="#一个典型的自查流程" aria-label="Permalink to &quot;一个典型的自查流程&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[&quot;游戏有问题&quot;] --&gt; B[&quot;打开日志页&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C{&quot;按级别看&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt;|&quot;点错误&quot;| D{&quot;有红色行？&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt;|&quot;点告警&quot;| E{&quot;有橙色行？&quot;}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt;|有| F[&quot;看具体内容&lt;br/&gt;这是真问题&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt;|没有| G[&quot;点全部&lt;br/&gt;看上下文&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt;|有| H[&quot;多半是 Mod 冲突&lt;br/&gt;去 Mod 页&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt;|没有| G</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G --&gt; I[&quot;复制全部日志&lt;br/&gt;发给作者&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">排查的第一步永远是「按错误筛」</p><p>如果「错误」筛选下<strong>一条都没有</strong>，说明框架没抓到异常 —— 问题可能不在框架层（可能是游戏本体、设备性能、或者 Mod 的配置逻辑）。</p><p>这时候「复制全部日志」发出去，让人帮你判断。</p></div><h2 id="常见的日志内容对照" tabindex="-1">常见的日志内容对照 <a class="header-anchor" href="#常见的日志内容对照" aria-label="Permalink to &quot;常见的日志内容对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>日志内容</th><th>级别</th><th>什么意思</th></tr></thead><tbody><tr><td>「加载 Mod [X]」</td><td>信息</td><td>正常加载</td></tr><tr><td>「Mod [A] 与 [B] 间重名」</td><td>告警</td><td>两个 Mod 冲突，后者覆盖前者</td></tr><tr><td>「找不到舰级 [X]」</td><td>告警</td><td>编队里写的舰级名不存在，那艘被跳过</td></tr><tr><td>「包内找不到资产」</td><td>告警</td><td>模型包里没有指定的 Prefab</td></tr><tr><td>「[UnityError] …」</td><td>错误</td><td>游戏引擎报错了</td></tr><tr><td>「保存存档失败」</td><td>错误</td><td>写盘失败</td></tr></tbody></table><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="日志是空的" tabindex="-1">日志是空的 <a class="header-anchor" href="#日志是空的" aria-label="Permalink to &quot;日志是空的&quot;">​</a></h3><p><strong>正常。</strong> 如果一切正常且没开 <code>debug.verbose</code>，日志内容会很少。</p><h3 id="日志太多-找不到重点" tabindex="-1">日志太多，找不到重点 <a class="header-anchor" href="#日志太多-找不到重点" aria-label="Permalink to &quot;日志太多，找不到重点&quot;">​</a></h3><p><strong>用筛选。</strong> 点「告警」或「错误」。</p><h3 id="复制按钮点了没反应" tabindex="-1">复制按钮点了没反应 <a class="header-anchor" href="#复制按钮点了没反应" aria-label="Permalink to &quot;复制按钮点了没反应&quot;">​</a></h3><p>部分安卓设备对剪贴板有限制。尝试：</p><ul><li>用文件管理器直接打开 <code>AFMOD_log.txt</code> 看</li><li>或者把文件复制出来发给别人</li></ul><h3 id="日志文件太大" tabindex="-1">日志文件太大 <a class="header-anchor" href="#日志文件太大" aria-label="Permalink to &quot;日志文件太大&quot;">​</a></h3><p>框架会自动截断（保留 200 KB，且保留最近的部分）。所以不会无限增长。</p><p>如果你想清空它，删掉文件即可（会自动重建）。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>出问题的系统排查 → <a href="/AtlanticFleetSite/docs/use/troubleshooting">出问题了怎么查</a></li><li>冲突怎么处理 → <a href="/AtlanticFleetSite/docs/use/conflicts">Mod 冲突排查</a></li><li>状态实时查看 → <a href="/AtlanticFleetSite/docs/use/status-page">状态页：看现场</a></li></ul>`,44)])])}const b=a(r,[["render",l]]);export{u as __pageData,b as default};
